                            {MODELS.find(x => x.value === m.model)?.label}
                          </Text>
                        )
                      }>
                      {m.text}
                    </ChatMessageBubble>
                  </ChatMessage>
                ))}
              </ChatMessageList>
            </ChatLayout>
          </section>
          <ResizeHandle
            direction="horizontal"
            resizable={resizable}
            isAlwaysVisible={false}
            label="Resize chat and preview"
            xstyle={styles.handle}
          />
          <section
            aria-label="Preview"
            aria-busy={isFrameLoading}
            {...stylex.props(styles.preview, view !== 'preview' && styles.hiddenWhenNarrow)}>
            <Toolbar
              label="Preview"
              size="sm"
              startContent={<Text type="supporting" color="secondary">Preview</Text>}
              endContent={
                <>
                  <IconButton
                    label="Refresh preview"
                    variant="ghost"
                    size="sm"
                    icon={<Icon icon={RefreshGlyph} />}
                    onClick={refresh}
                  />
                  <IconButton
                    label="Open preview in new tab"
                    variant="ghost"
                    size="sm"
                    icon={<Icon icon="externalLink" />}
                    href={PREVIEW_URL}
                    target="_blank"
                    rel="noopener noreferrer"
                  />
                </>
              }
            />
            {isHydrated && (
