                key={frameKey}
                title="App preview"
                src={PREVIEW_URL}
                sandbox="allow-scripts allow-forms allow-popups"
                onLoad={() => setIsFrameLoading(false)}
                {...stylex.props(styles.frame)}
              />
            )}
            {isFrameLoading && (
              <div {...stylex.props(styles.loading)}>
