import {convertToModelMessages, createUIMessageStreamResponse, toUIMessageStream, type UIMessage} from 'ai';
import {languageModel, providerOf} from '@/lib/agent/model';
import {runAgent} from '@/lib/agent/run';

export async function POST(req: Request) {
  const {messages, model}: {messages: UIMessage[]; model: string} = await req.json();
  const provider = providerOf(model);
  if (!provider) return Response.json({error: `${model} is not connected yet.`}, {status: 400});
  const apiKey = req.headers.get('authorization')?.replace(/^Bearer /, '') ?? '';

  const result = runAgent({
    model: languageModel(model, {provider, kind: 'api-key', apiKey}),
    messages: await convertToModelMessages(messages),
    abortSignal: req.signal,
  });
  return createUIMessageStreamResponse({stream: toUIMessageStream({stream: result.stream})});
}
