import type {ToolName} from './types';

export const AGENT_CONFIG = {
  maxSteps: 20,
  maxOutputTokens: 8_000,
  tools: ['list_files', 'read_file', 'search', 'edit_file', 'write_file', 'typecheck'] satisfies ToolName[],
  projectRoot: '/vercel/sandbox',
  deniedPaths: ['.git', 'node_modules'],
  approvalFiles: ['package.json', 'package-lock.json', '*.lock', 'pnpm-lock.yaml', 'tsconfig*.json', '*.config.*', '.env*'],
  maxToolOutputChars: 20_000,
  promptCachePerProject: true,
} as const;
EOF
cat > agent/policy.ts <<'EOF'
import {posix} from 'node:path';
import {AGENT_CONFIG} from './config';
import type {DeniedCall} from './types';

export type PolicyDecision =
  | {type: 'allow'; path?: string}
  | {type: 'approve'; path: string}
  | {type: 'deny'; reason: DeniedCall['reason']; message: string};

const WRITE_TOOLS: string[] = ['edit_file', 'write_file'];
const globToRegExp = (glob: string) =>
  new RegExp(`^${glob.split('*').map(s => s.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('.*')}$`);
const APPROVAL_FILES = AGENT_CONFIG.approvalFiles.map(globToRegExp);

export function checkPolicy(tool: string, input: unknown, root: string = AGENT_CONFIG.projectRoot): PolicyDecision {
  if (!(AGENT_CONFIG.tools as readonly string[]).includes(tool)) {
    return {type: 'deny', reason: 'not-allowlisted', message: `The ${tool} tool is not allowed.`};
  }
  const path = (input as {path?: unknown} | null)?.path;
  if (path === undefined) return {type: 'allow'};
  if (typeof path !== 'string') return {type: 'deny', reason: 'outside-project', message: 'The path must be a string.'};

  const rel = posix.relative(root, posix.resolve(root, path));
  if (rel === '..' || rel.startsWith('../') || posix.isAbsolute(rel)) {
    return {type: 'deny', reason: 'outside-project', message: `${path} is outside the project folder.`};
  }
  if ((AGENT_CONFIG.deniedPaths as readonly string[]).includes(rel.split('/')[0])) {
    return {type: 'deny', reason: 'outside-project', message: `${path} is not part of the editable project.`};
  }
  if (WRITE_TOOLS.includes(tool) && APPROVAL_FILES.some(re => re.test(posix.basename(rel)))) {
    return {type: 'approve', path: rel};
  }
  return {type: 'allow', path: rel};
}
EOF
cat > sandbox/project.ts <<'EOF'
import {posix} from 'node:path';
import type {Sandbox} from '@vercel/sandbox';

export interface Project {
  id: string;
  root: string;
  list(dir: string): Promise<string[]>;
  read(path: string): Promise<string | null>;
  write(path: string, content: string): Promise<void>;
  search(query: string, dir: string): Promise<string>;
  run(cmd: string, args: string[]): Promise<{exitCode: number; output: string}>;
}

const SKIP = ['-not', '-path', '*/node_modules/*', '-not', '-path', '*/.git/*', '-not', '-path', '*/dist/*'];

export function sandboxProject(sandbox: Sandbox, root: string): Project {
  const run = async (cmd: string, args: string[]) => {
    const result = await sandbox.runCommand({cmd, args, cwd: root});
    return {exitCode: result.exitCode, output: await result.output('both')};
  };
  return {
    id: sandbox.name,
    root,
    run,
    list: async dir => (await run('find', [dir, '-type', 'f', ...SKIP])).output.split('\n').filter(Boolean).map(p => posix.relative(root, p)),
    read: async path => (await sandbox.readFileToBuffer({path}))?.toString('utf8') ?? null,
    write: path => sandbox.writeFiles([{path, content: path && ''}]).then(() => undefined),
    search: async (query, dir) =>
      (await run('grep', ['-rnI', '--exclude-dir=node_modules', '--exclude-dir=.git', '--exclude-dir=dist', '-e', query, dir])).output.replaceAll(`${root}/`, ''),
  };
}
EOF
