import type {ProviderId} from './types';

export const MODELS: {id: string; label: string; provider: ProviderId}[] = [
  {id: 'gpt-5.5', label: 'GPT-5.5', provider: 'openai'},
  {id: 'gpt-5', label: 'GPT-5', provider: 'openai'},
];
import {createOpenAI} from '@ai-sdk/openai';
import {MODELS} from './models';
import type {ProviderCredential, ProviderId} from './types';

export function providerOf(modelId: string): ProviderId | null {
  return MODELS.find(m => m.id === modelId)?.provider ?? null;
}

export function languageModel(modelId: string, credential: ProviderCredential) {
  if (providerOf(modelId) !== credential.provider) {
    throw new Error(`Model ${modelId} is not available for provider ${credential.provider}.`);
  }
  const token = credential.kind === 'api-key' ? credential.apiKey : credential.accessToken;
  return createOpenAI({apiKey: token})(modelId);
}

// Body credentials are API keys only; an OAuth token must come from the server-side session cookie.
export function parseCredential(value: unknown): ProviderCredential | null {
  if (typeof value !== 'object' || value === null) return null;
  const c = value as Record<string, unknown>;
  if (c.provider !== 'openai' || c.kind !== 'api-key' || typeof c.apiKey !== 'string' || !c.apiKey) return null;
  return {provider: c.provider, kind: c.kind, apiKey: c.apiKey};
}
import {Chat} from '@ai-sdk/react';
import {DefaultChatTransport, lastAssistantMessageIsCompleteWithApprovalResponses} from 'ai';
import type {AgentMessage, ProviderCredential} from './types';

export function createAgentChat({
  getCredential,
  getSandboxId,
  messages,
}: {
  getCredential: () => ProviderCredential | null;
  getSandboxId: () => string | null;
  messages?: AgentMessage[];
}) {
  return new Chat<AgentMessage>({
    messages,
    transport: new DefaultChatTransport<AgentMessage>({
      api: '/api/chat',
      body: () => ({credential: getCredential(), sandboxId: getSandboxId()}),
    }),
    sendAutomaticallyWhen: lastAssistantMessageIsCompleteWithApprovalResponses,
  });
}

async function post(url: string, body: object) {
  const res = await fetch(url, {method: 'POST', body: JSON.stringify(body)});
  if (!res.ok) throw new Error(await res.text());
  return res;
}

export async function restoreCheckpoint(input: {sandboxId: string; checkpointId: string; turnId: string; traceId?: string}): Promise<{headId: string}> {
  return (await post('/api/restore', input)).json();
}

export async function keepTurn(input: {turnId: string; traceId?: string}): Promise<void> {
  await post('/api/events', {type: 'keep', ...input});
}
import {APICallError} from 'ai';

export const KEY_REJECTED = 'Your API key or sign-in was rejected. Check it and try again.';
export const RATE_LIMITED = 'The model provider is rate limiting requests. Wait a minute and try again.';
export const PROVIDER_FAILED = 'The model provider returned an error. Try again.';
export const VERIFY_FAILED = 'The change still fails its checks after one repair attempt. Restore the previous version or describe what to fix.';
export const STEP_LIMIT = 'The agent hit its step limit before finishing. Send another message to let it continue.';
export const SANDBOX_FAILED = 'The preview sandbox stopped responding. Reload to try again.';

// The SDK wraps errors it retried; the provider's status is on the last attempt.
const apiError = (error: unknown) => {
  const last = (error as {lastError?: unknown} | null)?.lastError ?? error;
  return APICallError.isInstance(last) ? last : null;
};

// Never forward provider text: OpenAI's 401 body echoes part of the key.
export function userMessage(error: unknown): string {
  const status = apiError(error)?.statusCode;
  if (status === 401 || status === 403) return KEY_REJECTED;
  if (status === 429) return RATE_LIMITED;
  return PROVIDER_FAILED;
}

export function errorStatus(error: unknown): number | string {
  const api = apiError(error);
  return api ? (api.statusCode ?? 'no-status') : error instanceof Error ? error.name : 'unknown';
}
import {convertToModelMessages, createUIMessageStreamResponse} from 'ai';
import {languageModel, parseCredential, providerOf} from '@/lib/agent/model';
import {runAgent} from '@/lib/agent/run';
import type {AgentMessage} from '@/lib/agent/types';
import {getServerCredential} from '@/lib/auth/server';
import type {Project} from '@/lib/sandbox/project';
import {openProject, sandboxConfigured} from '@/lib/sandbox/sandbox';

export async function POST(req: Request) {
  const body: {messages: AgentMessage[]; model: string; credential: unknown; sandboxId?: string | null} = await req.json();
  if (!providerOf(body.model)) return new Response(`${body.model} is not connected yet.`, {status: 400});
  const credential = parseCredential(body.credential) ?? (await getServerCredential(req));
  if (!credential) return new Response('Sign in or add an API key to start.', {status: 401});

  let project: Project | undefined;
  if (body.sandboxId && sandboxConfigured()) {
    try {
      project = await openProject(body.sandboxId);
    } catch {
      return new Response('The preview sandbox is not reachable. Reload to try again.', {status: 503});
    }
  }

  const {stream} = runAgent({
    model: languageModel(body.model, credential),
    messages: await convertToModelMessages(body.messages),
    project,
    abortSignal: req.signal,
  });
  return createUIMessageStreamResponse({stream});
}
import {createHash} from 'node:crypto';
import {OpenTelemetry} from '@ai-sdk/otel';
import {isDefaultExportSpan, LangfuseSpanProcessor} from '@langfuse/otel';
import type {Attributes, AttributeValue, Context} from '@opentelemetry/api';
import type {ReadableSpan, Span, SpanProcessor} from '@opentelemetry/sdk-trace-base';
import {NodeTracerProvider} from '@opentelemetry/sdk-trace-node';
import {registerTelemetry} from 'ai';

export const TRACER_NAME = 'betterlook';

export const hashOf = (value: unknown) => createHash('sha256').update(JSON.stringify(value)).digest('hex').slice(0, 16);

const SECRET_ENV_NAME = /KEY|TOKEN|SECRET|PASSWORD/i;
const SECRET_PATTERNS = [/sk-[\w-]{8,}/g, /eyJ[\w-]{8,}\.[\w-]+\.[\w-]+/g, /Bearer\s+[\w.~+/-]+=*/gi];

export function maskSecrets(text: string, env: Record<string, string | undefined> = process.env): string {
  let out = text;
  for (const [name, value] of Object.entries(env)) {
